import { lstat, mkdir, readlink, symlink } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";

export const name = "szfc";
export const inject = [];

const DEFAULTS = [
  "zentao-analyzer",
  "worktree-snapshot",
  "submodule-commit",
  "dsh-token-policy",
  "repo-safety",
  "web-deploy",
];

function normalize(input) {
  return {
    enabled: input?.enabled ?? true,
    skillsRoot: input?.skillsRoot ?? "D:/repository/skills",
    link: Array.isArray(input?.link) && input.link.length ? input.link : DEFAULTS,
  };
}

export async function linkSkills(config = normalize()) {
  const destRoot = join(homedir(), ".dsh", "skills");
  await mkdir(destRoot, { recursive: true });
  const linked = [];
  for (const name of config.link) {
    const target = join(config.skillsRoot, name);
    const dest = join(destRoot, name);
    let existing;
    try {
      existing = await lstat(dest);
    } catch {
      existing = undefined;
    }
    if (existing?.isSymbolicLink()) {
      const current = await readlink(dest);
      if (current === target) continue;
    }
    if (existing) continue;
    await symlink(target, dest, "junction");
    linked.push(name);
  }
  return linked;
}

export function apply(ctx, rawConfig) {
  const config = normalize(rawConfig);
  if (!config.enabled) return;
  linkSkills(config).then(
    (linked) => {
      if (linked.length) ctx.logger?.info?.(`dsh-szfc linked: ${linked.join(", ")}`);
    },
    (error) => ctx.logger?.warn?.(`dsh-szfc link failed: ${error?.message ?? error}`),
  );
}
